import { getLocalData } from '../utils/storage';

// Dữ liệu mẫu để hiển thị thống kê
const stats = [
  { label: 'Tổng nhân viên', value: '24', color: '#2563eb' },
  { label: 'Phòng ban', value: '5', color: '#16a34a' },
  { label: 'Đang nghỉ phép', value: '3', color: '#d97706' },
  { label: 'Chấm công hôm nay', value: '21', color: '#7c3aed' },
];

function Dashboard() {
  const currentUser = getLocalData('currentUser');
  const name = currentUser ? currentUser.name || currentUser.username : 'bạn';

  return (
    <div>
      <h4 style={{ marginBottom: '4px', color: '#111' }}>Dashboard</h4>
      <p style={{ color: '#888', fontSize: '14px', marginBottom: '24px' }}>
        Xin chào, {name}! Đây là tổng quan hệ thống.
      </p>

      {/* Các thẻ thống kê */}
      <div style={{ display: 'flex', gap: '16px', flexWrap: 'wrap', marginBottom: '32px' }}>
        {stats.map((stat) => (
          <div
            key={stat.label}
            style={{
              backgroundColor: '#fff',
              border: '1px solid #ddd',
              borderRadius: '8px',
              padding: '20px 24px',
              minWidth: '160px',
              flex: '1'
            }}
          >
            <p style={{ margin: 0, fontSize: '13px', color: '#888' }}>{stat.label}</p>
            <p style={{ margin: '8px 0 0', fontSize: '28px', fontWeight: 'bold', color: stat.color }}>
              {stat.value}
            </p>
          </div>
        ))}
      </div>

      {/* Hoạt động gần đây */}
      <div style={{
        backgroundColor: '#fff',
        border: '1px solid #ddd',
        borderRadius: '8px',
        padding: '20px'
      }}>
        <h6 style={{ marginBottom: '16px', color: '#333' }}>Hoạt động gần đây</h6>
        <ul style={{ listStyle: 'none', margin: 0, padding: 0 }}>
          {[
            'Nguyễn Văn A đã gửi đơn xin nghỉ phép.',
            'Phòng Kỹ thuật cập nhật danh sách nhân viên.',
            'Chấm công ngày 22/05 đã được ghi nhận.',
            'Trần Thị B được thêm vào phòng Marketing.',
          ].map((item, i) => (
            <li key={i} style={{
              padding: '10px 0',
              borderBottom: i < 3 ? '1px solid #f0f0f0' : 'none',
              fontSize: '14px',
              color: '#555'
            }}>
              {item}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

export default Dashboard;
